const CARDS={
  hakken:{n:'第一発見者',r:'だいいちはっけんしゃ',c:'#2f8fd8',t:'さいしょに出すカード。持っている人が じけんを見つけて、ゲームがはじまる。'},
  hannin:{n:'犯人',r:'はんにん',c:'#2fa65a',t:'手札が この1まいだけになったら出せる。出せたら 犯人の勝ち!'},
  tantei:{n:'探偵',r:'たんてい',c:'#e8559a',t:'だれか1人に「犯人ですか?」ときく。当たれば勝ち! 手札が3まい以下のときに使える。'},
  alibi:{n:'アリバイ',r:'ありばい',c:'#e2543f',t:'出しても 何もおきない。持っていると 探偵にきかれても「ちがいます」と言える。'},
  takurami:{n:'たくらみ',r:'たくらみ',c:'#3fb0e3',t:'出すと 犯人のなかまになる。犯人が勝てば いっしょに勝ち。つかまったら いっしょに負け。'},
  mokugeki:{n:'目撃者',r:'もくげきしゃ',c:'#9a6a3e',t:'だれか1人の手札を こっそり ぜんぶ見る。'},
  sousa:{n:'情報操作',r:'じょうほうそうさ',c:'#86c43a',t:'みんな 手札を1まい えらんで、つぎの人(左どなり)にわたす。'},
  uwasa:{n:'うわさ',r:'うわさ',c:'#f0b928',t:'みんな、まえの人(右どなり)の手札から 1まい ひく。'},
  torihiki:{n:'取り引き',r:'とりひき',c:'#8a3fb8',t:'だれか1人と、手札を1まいずつ こうかんする。'},
  inu:{n:'いぬ',r:'いぬ',c:'#2a62c9',t:'だれかの手札から1まい くわえてくる。犯人カードなら 勝ち!'},
  shonen:{n:'少年',r:'しょうねん',c:'#1f2f7a',t:'犯人カードを持っている人が こっそりわかる。(アリバイがあっても わかる)'},
  ippan:{n:'一般人',r:'いっぱんじん',c:'#1f9a9a',t:'何もおきない。'}
};
const DECK_COUNTS={hakken:1,hannin:1,tantei:4,alibi:5,takurami:2,mokugeki:3,sousa:3,uwasa:4,torihiki:5,inu:1,shonen:1,ippan:2};
const OTHERS=['mokugeki','sousa','uwasa','torihiki','inu','shonen','ippan'];
const NEEDS_TARGET={tantei:1,mokugeki:1,inu:1,torihiki:1};
let G=null,uidc=0;

function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const rand=a=>a[Math.floor(Math.random()*a.length)];
const mk=t=>({type:t,uid:++uidc,fresh:false});
const has=(P,t)=>P.hand.some(c=>c.type===t);
const nm=t=>CARDS[t].n;

function buildDeck(n){
  const fixed=['hakken','hannin','tantei','alibi'];
  if(n>=4)fixed.push('takurami');
  const pool=[];OTHERS.forEach(t=>{for(let k=0;k<DECK_COUNTS[t];k++)pool.push(t);});
  shuffle(pool);
  return shuffle(fixed.concat(pool.slice(0,n*4-fixed.length))).map(mk);
}
function newGame(seats){
  const n=seats.length,deck=buildDeck(n);
  G={n,players:seats.map((s,i)=>({name:s.name,cpu:s.cpu,av:s.av,idx:i,hand:deck.slice(i*4,i*4+4),acc:false,know:null})),
     last:null,lastBy:-1,turn:-1,over:false,result:null,log:[],viewer:null};
  G.players.forEach(P=>{if(P.cpu){P.know=G.players.map(()=>1);normK(P.idx);}});
}
function canPlay(P,c){
  if(c.type==='hannin')return P.hand.length===1;
  if(c.type==='tantei')return P.hand.length<=3;
  if(c.type==='hakken')return false;
  return true;
}
function whyNot(P,c){
  if(c.type==='hannin')return '手札がこの1まいだけになったら 出せる';
  if(c.type==='tantei')return '手札が3まい以下になったら 使える';
  return '';
}
function legalIdx(P){
  let l=P.hand.map((c,i)=>canPlay(P,c)?i:-1).filter(i=>i>=0);
  if(!l.length)l=P.hand.map((c,i)=>c.type!=='hannin'?i:-1).filter(i=>i>=0);
  if(!l.length)l=[0];
  return l;
}
const withCards=(ex)=>G.players.filter(q=>q.idx!==ex&&q.hand.length>0).map(q=>q.idx);

/* ---- CPU knowledge: probability that each player holds 犯人 ---- */
function normK(k){
  const P=G.players[k],p=P.know;
  if(has(P,'hannin')){p.fill(0);p[k]=1;return;}
  p[k]=0;G.players.forEach((q,i)=>{if(!q.hand.length)p[i]=0;});
  let s=p.reduce((a,b)=>a+b,0);
  if(s<=1e-9){G.players.forEach((q,i)=>{p[i]=(i!==k&&q.hand.length)?q.hand.length:0;});s=p.reduce((a,b)=>a+b,0);}
  for(let i=0;i<p.length;i++)p[i]/=(s||1);
}
function knowTransfer(trs,sizes){
  G.players.forEach(P=>{
    if(!P.cpu)return;
    const k=P.idx,p=P.know,np=p.slice();let certain=-1;
    trs.forEach(tr=>{
      const mine=tr.from===k||tr.to===k;
      const f=mine?(tr.card.type==='hannin'?1:0):1/Math.max(1,sizes[tr.from]);
      const m=p[tr.from]*f;np[tr.from]-=m;np[tr.to]+=m;
      if(mine&&tr.card.type==='hannin')certain=tr.to;
    });
    if(certain>=0){np.fill(0);np[certain]=1;}
    P.know=np.map(x=>Math.max(0,x));normK(k);
  });
}
function knowAll(fn){G.players.forEach(P=>{if(P.cpu){fn(P.know,P.idx);normK(P.idx);}});}
function knowSee(k,y){
  const P=G.players[k];if(!P.cpu)return;
  if(has(G.players[y],'hannin')){P.know.fill(0);P.know[y]=1;}else P.know[y]=0;
  normK(k);
}

/* ---- CPU decisions ---- */
function bestGuess(P){
  let tgt=-1,conf=-1;
  withCards(P.idx).forEach(o=>{if(P.know[o]>conf){conf=P.know[o];tgt=o;}});
  return {tgt,conf:Math.max(0,conf)};
}
function cpuChoose(i){
  const P=G.players[i],crim=has(P,'hannin'),{tgt,conf}=bestGuess(P),others=withCards(i);
  const sc={
    hannin:()=>1000,
    tantei:()=>crim?8:(conf>=.6?900:(P.hand.length<=2&&conf>=.4?300:12+conf*30)),
    inu:()=>crim?26:(conf>=.6?700:40+conf*80),
    shonen:()=>crim?30:(conf>=.95?20:500),
    mokugeki:()=>crim?34:(conf>=.95?18:220),
    takurami:()=>crim?60:38,
    ippan:()=>50,
    alibi:()=>crim?(P.hand.length<=2?0:2):46,
    uwasa:()=>crim?20:42,sousa:()=>crim?44:42,torihiki:()=>crim?40:42,
    hakken:()=>-99
  };
  const legal=legalIdx(P);let best=legal[0],bs=-1e9;
  legal.forEach(ci=>{const s=sc[P.hand[ci].type]()+Math.random()*10;if(s>bs){bs=s;best=ci;}});
  const type=P.hand[best].type;let target=null;
  if(NEEDS_TARGET[type]&&others.length){
    if(crim||type==='torihiki'||tgt<0)target=rand(others);else target=tgt;
  }
  return {ci:best,target};
}
function giveVal(P,c){
  const crim=has(P,'hannin');
  return ({ippan:1,alibi:crim?60:2,takurami:3,uwasa:4,sousa:4,torihiki:4,mokugeki:6,inu:7,tantei:8,shonen:8,hannin:100,hakken:0})[c.type];
}
function cpuGive(i){
  const P=G.players[i];
  const hi=P.hand.findIndex(c=>c.type==='hannin');
  if(hi>=0&&P.hand.length>1&&Math.random()<0.2)return hi;
  let b=0,bv=1e9;P.hand.forEach((c,ci)=>{const v=giveVal(P,c)+Math.random()*1.5;if(v<bv){bv=v;b=ci;}});
  return b;
}

/* ---- game flow ---- */
const W=P=>`\u0001${P.idx}\u0002`;
function log(s){G.log.push(s);if(G.log.length>30)G.log.shift();UI.render();}
async function chooseGive(i,title){
  const P=G.players[i];
  if(P.cpu)return cpuGive(i);
  await UI.ensureViewer(i);
  return await UI.pickGive(i,title);
}
async function runGame(){
  const s=G.players.findIndex(P=>has(P,'hakken'));
  const P=G.players[s],hi=P.hand.findIndex(c=>c.type==='hakken');
  G.turn=s;UI.render();
  await UI.wait(500);
  await UI.flyPlay(s,P.hand[hi],s===G.viewer?document.querySelector(`#hand .card[data-ci="${hi}"]`):null);
  const c=P.hand.splice(hi,1)[0];G.last=c;G.lastBy=s;G.lastTo=null;
  UI.sfx('play');
  log(`${W(P)} が 第一発見者! じけんが おきた…`);
  await UI.announce(s,`<p class="lead"><b>${P.name}</b> が じけんを はっけん!</p><p>犯人は この中に いる…</p>`,null,null,Math.max(2200,pace().read));
  let t=(s+1)%G.n,guard=0;
  while(!G.over&&guard++<500){
    if(G.players[t].hand.length)await takeTurn(t);
    t=(t+1)%G.n;
  }
}
async function takeTurn(i){
  const P=G.players[i];G.turn=i;G.turnNo=(G.turnNo||0)+1;UI.render();
  let ch;
  if(P.cpu){UI.sfx('turn');await UI.wait(thinkMs(P));ch=cpuChoose(i);}
  else{await UI.ensureViewer(i);ch=await UI.humanTurn(i);}
  await resolvePlay(i,ch.ci,ch.target);
  // 出したカードと、その結果 (記録の行) を読む間。タップすれば待たずに次へ
  if(P.cpu&&!G.over&&G.last)await UI.readPause(Math.max(450,pace().read*(READ_W[G.last.type]??.6)));
  P.hand.forEach(c=>c.fresh=false);
  UI.afterTurn(i);
}
function setMood(i,m,ms){const P=G.players[i];P.mood=m;UI.render();if(ms)setTimeout(()=>{if(G&&!G.over&&P.mood===m){P.mood='normal';UI.render();}},ms);}
async function resolvePlay(i,ci,target){
  const P0=G.players[i];
  await UI.flyPlay(i,P0.hand[ci],i===G.viewer?document.querySelector(`#hand .card[data-ci="${ci}"]`):null);
  const P=G.players[i],c=P.hand.splice(ci,1)[0],T=target!=null?G.players[target]:null;
  G.last=c;G.lastBy=i;G.lastTo=T?target:null;UI.sfx('play');
  log(`\u0003${W(P)}「${nm(c.type)}」`+(T?` → ${W(T)}`:''));
  await UI.wait(P.cpu?450:200);
  switch(c.type){
    case 'hannin':
      return endGame('hannin',i,i);
    case 'tantei':{
      if(!T){log('きく相手が いない…');break;}
      const isC=has(T,'hannin'),yes=isC&&!has(T,'alibi');
      await UI.announce(i,`<div class="speech">「${T.name}さん、あなたが 犯人ですね?」</div>`,null,null,Math.max(1500,pace().read*.7));
      UI.sfx('drum');await UI.wait(Math.round(pace().think*1.6));
      if(yes){UI.sfx('hit');setMood(target,'shock');await UI.announce(target,`<div class="speech">「……はい。わたしが 犯人です。」</div>`,null,'shock');return endGame('tantei',i,target);}
      UI.sfx('miss');
      await UI.announce(target,`<div class="speech">「いいえ、ちがいます。」</div>`,null,'happy',Math.max(1500,pace().read*.7));setMood(i,'sad',2500);
      log(`${W(T)}「ちがいます」`);
      knowAll(p=>{if(p[target]<.999)p[target]*=.25;});
      break;}
    case 'alibi':case 'ippan':log('…とくに何もおきない');break;
    case 'takurami':P.acc=true;log(`${W(P)} は 犯人のなかまに なった!`);break;
    case 'mokugeki':
      if(!T){log('見る相手が いない…');break;}
      if(P.cpu)knowSee(i,target);
      else await UI.privateMsg(i,`<h2>${T.name} の手札</h2>`,T.hand);
      log(`${W(P)} は ${W(T)} の手札を こっそり見た`);
      break;
    case 'shonen':{
      const h=G.players.findIndex(q=>has(q,'hannin'));
      if(P.cpu){P.know.fill(0);P.know[h]=1;normK(i);}
      else await UI.privateMsg(i,`<h2>少年が 見たもの…</h2><div class="big-av">${avatarSVG(G.players[h].av,'shock')}</div><p>犯人カードを持っているのは<br><b style="font-size:20px">${h===i?'あなた じしん!':G.players[h].name}</b></p>`);
      log(`${W(P)} は 犯人を こっそり知った…`);
      break;}
    case 'inu':{
      if(!T){log('いぬは ねむっている…');break;}
      const k=Math.floor(Math.random()*T.hand.length),got=T.hand[k];
      UI.sfx('dog');
      await UI.fly(UI.spot(target),UI.tableSpot(),cardHTML(got,{cls:'flyc'}),600);
      await UI.announce(i,`<p>いぬが <b>${T.name}</b> の手札から 1まい くわえてきた!</p>`,got);
      if(got.type==='hannin'){UI.sfx('hit');setMood(target,'shock');return endGame('inu',i,target);}
      log(`いぬは「${nm(got.type)}」をくわえてきた。${W(T)} にかえした`);
      const h=T.hand.length;knowAll(p=>{if(p[target]<.999)p[target]*=(h-1)/h;});
      break;}
    case 'torihiki':{
      if(!T||!P.hand.length){log('こうかんできる カードが ない…');break;}
      const sizes=G.players.map(q=>q.hand.length);
      const a=await chooseGive(i,`${T.name} に わたすカードを えらんでね`);
      const b=await chooseGive(target,`${P.name} と取り引き! わたすカードを えらんでね`);
      const ca=P.hand[a],cb=T.hand[b];
      P.hand.splice(a,1,cb);T.hand.splice(b,1,ca);cb.fresh=true;ca.fresh=true;
      knowTransfer([{from:i,to:target,card:ca},{from:target,to:i,card:cb}],sizes);
      UI.sfx('swap');
      log(`${W(P)} と ${W(T)} が カードを こうかんした`);
      await UI.moveNotice([{from:i,to:target,card:ca},{from:target,to:i,card:cb}]);
      break;}
    case 'uwasa':case 'sousa':{
      const act=G.players.filter(q=>q.hand.length).map(q=>q.idx);
      if(act.length<2){log('…でも、だれにも とどかなかった');break;}
      const sizes=G.players.map(q=>q.hand.length),trs=[];
      for(let x=0;x<act.length;x++){
        const giver=act[x],to=act[(x+1)%act.length];
        let gi;
        if(c.type==='uwasa')gi=Math.floor(Math.random()*G.players[giver].hand.length);
        else gi=await chooseGive(giver,`情報操作! ${G.players[to].name} に わたすカードを えらんでね`);
        trs.push({from:giver,to,card:G.players[giver].hand[gi]});
      }
      trs.forEach(tr=>{const H=G.players[tr.from].hand;H.splice(H.indexOf(tr.card),1);});
      trs.forEach(tr=>{tr.card.fresh=true;G.players[tr.to].hand.push(tr.card);});
      knowTransfer(trs,sizes);
      UI.sfx('swap');
      log(c.type==='uwasa'?'みんな まえの人から 1まい ひいた':'みんな つぎの人に 1まい わたした');
      await UI.moveNotice(trs);
      break;}
  }
  UI.render();
}
function endGame(kind,actor,crimIdx){
  G.over=true;
  G.players.forEach(P=>P.mood='normal');
  const winners=G.players.filter(P=>{
    const crimSide=P.idx===crimIdx||P.acc;
    return kind==='hannin'?crimSide:!crimSide;
  }).map(P=>P.idx);
  G.result={kind,actor,crimIdx,winners};
  G.players.forEach(P=>{P.mood=winners.includes(P.idx)?'happy':(P.idx===crimIdx&&kind!=='hannin'?'shock':'sad');});
  UI.render();UI.showResult();
}

const FACES={"kid_normal": "data:image/webp;base64,", "cat_normal": "data:image/webp;base64,", "fox_normal": "data:image/webp;base64,", "owl_normal": "data:image/webp;base64,", "kid_happy": "data:image/webp;base64,", "cat_happy": "data:image/webp;base64,", "fox_happy": "data:image/webp;base64,", "owl_happy": "data:image/webp;base64,", "kid_sad": "data:image/webp;base64,", "cat_sad": "data:image/webp;base64,", "fox_sad": "data:image/webp;base64,", "owl_sad": "data:image/webp;base64,", "kid_shock": "data:image/webp;base64,", "cat_shock": "data:image/webp;base64,", "fox_shock": "data:image/webp;base64,", "owl_shock": "data:image/webp;base64,"};
function avatarSVG(kind,mood){
  if(!FACES[kind+'_normal'])kind='kid';
  return `<img class="av" alt="" draggable="false" src="${FACES[kind+'_'+(mood||'normal')]||FACES[kind+'_normal']}">`;
}
const ART={"hakken": "data:image/webp;base64,", "hannin": "data:image/webp;base64,", "tantei": "data:image/webp;base64,", "alibi": "data:image/webp;base64,", "takurami": "data:image/webp;base64,", "mokugeki": "data:image/webp;base64,", "sousa": "data:image/webp;base64,", "uwasa": "data:image/webp;base64,", "torihiki": "data:image/webp;base64,", "inu": "data:image/webp;base64,", "shonen": "data:image/webp;base64,", "ippan": "data:image/webp;base64,"};
function cardArt(t){return `<img class="art" alt="" draggable="false" src="${ART[t]}">`;}
function cardHTML(c,opt={}){
  const C=CARDS[c.type];
  return `<div class="card ${opt.cls||''}" style="--c:${C.c}" ${opt.data||''}>${c.fresh&&opt.fresh?'<span class="new">NEW</span>':''}
    <div class="cn ${C.n.length>=4?'long':''}">${C.n}</div>${cardArt(c.type)}<div class="cr ${C.r.length>=8?'long':''}">${C.r}</div></div>`;
}

const $=s=>document.querySelector(s);
const AVS=['kid','cat','fox','owl'];
// キャラの色 (顔の絵の地の色)。タイルの名札と顔の輪に使う
const AVC={kid:'#3d8bf2',cat:'#8058b3',fox:'#3e965f',owl:'#a0624e'};
const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
// 小さな顔 + キャラの色の名前 (字を読まなくても、だれのことか分かるように)
// 場のカードの下: 出した人 (と、相手) の顔 + 名札
function byHTML(P){return `<span class="who1" style="--pc:${AVC[P.av]||'#6f6f78'}">${avatarSVG(P.av)}<b>${esc(P.name)}</b></span>`;}
// 説明の行の名前は顔だけ (すぐ上の行に 顔 + 名札 が出ているので、名前の字までくり返すとうるさい。使う人に言われた)
function whoHTML(P){return P?`<span class="chip" role="img" aria-label="${esc(P.name)}" style="--pc:${AVC[P.av]||'#6f6f78'}">${avatarSVG(P.av)}</span>`:'';}
const DEF_NAMES=['あなた','くろねこ','きつね','ふくろう'];
let settings={n:4,seats:[{name:'あなた',cpu:false},{name:'くろねこ',cpu:true},{name:'きつね',cpu:true},{name:'ふくろう',cpu:true}],sound:true};
try{const s=JSON.parse(localStorage.getItem('yakata-settings'));if(s&&s.seats&&s.seats.length===4)settings=s;}catch(e){}
const save=()=>{try{localStorage.setItem('yakata-settings',JSON.stringify(settings));}catch(e){}};
// はやさ: CPU が考える間 (think) と、出したカードを読む間 (read)。ms
const PACES={slow:{label:'ゆっくり',think:650,read:4000},normal:{label:'ふつう',think:450,read:2800},fast:{label:'はやい',think:250,read:1400}};
if(!PACES[settings.speed])settings.speed='normal';
const pace=()=>PACES[settings.speed]||PACES.normal;
/* テンポの緩急。前は どのカードでも 1 手 4.17 秒 (考える 0.45 + 飛ぶ 0.46 + 間 0.45 + 読む 2.8) で、リズムが一定だった。
   何も起きないカードは さっと流し、起きたことが多いカードほど読む間をとる。知らせ (announce) を出したカードは、そこで読んでいるので短く */
const READ_W={alibi:.4,ippan:.4,hakken:.4,takurami:.6,mokugeki:.5,shonen:.5,uwasa:.8,sousa:.8,torihiki:.8,tantei:.25,inu:.25};
// 考える間も毎回同じにしない。乱数は使わない (配り方を決め打ちにしたテストの道すじを変えないため)。手の番号から決める
const THINK_W=[1,.7,1.35,.85,1.15,.6,1.5,.9];
function thinkMs(P){
  const base=pace().think*THINK_W[(G.turnNo||0)%THINK_W.length];
  if(P.hand.length<=1)return base*.5;                       // 出せるのが 1 まいなら迷わない
  if(P.hand.some(c=>c.type==='tantei'||c.type==='inu'))return base+pace().think*.8;   // 決め手を持っていると、少し考えこむ
  return base;
}

/* ---- sound ---- */
let AC=null;
function ac(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f,d,type='sine',v=.15,when=0,slide=0){
  const a=ac();if(!a||!settings.sound)return;const t=a.currentTime+when;
  const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(f,t);
  if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+d);
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+d);
  o.connect(g).connect(a.destination);o.start(t);o.stop(t+d+.05);
}
function noise(d,v=.12,f=2500){
  const a=ac();if(!a||!settings.sound)return;const t=a.currentTime;
  const b=a.createBuffer(1,a.sampleRate*d,a.sampleRate),x=b.getChannelData(0);for(let i=0;i<x.length;i++)x[i]=(Math.random()*2-1)*(1-i/x.length);
  const s=a.createBufferSource(),fl=a.createBiquadFilter(),g=a.createGain();s.buffer=b;fl.type='bandpass';fl.frequency.value=f;g.gain.value=v;
  s.connect(fl).connect(g).connect(a.destination);s.start(t);
}
const SFX={
  play:()=>noise(.12,.25,3000),tap:()=>tone(880,.06,'triangle',.08),
  swap:()=>{noise(.1,.2,2000);setTimeout(()=>noise(.1,.2,3200),120);},
  hit:()=>{[523,659,784,1047].forEach((f,i)=>tone(f,.25,'triangle',.14,i*.09));},
  miss:()=>{tone(330,.25,'sine',.12);tone(247,.35,'sine',.12,.18);},
  dog:()=>{tone(600,.08,'square',.06,0,400);tone(650,.08,'square',.06,.14,420);},
  win:()=>{[523,659,784,1047,1319].forEach((f,i)=>tone(f,.4,'triangle',.13,i*.1));},
  lose:()=>{[392,330,262,196].forEach((f,i)=>tone(f,.4,'sine',.12,i*.16));},
  secret:()=>{tone(1200,.5,'sine',.08);tone(1600,.6,'sine',.06,.12);},
  turn:()=>tone(520,.07,'sine',.05),
  myturn:()=>{tone(784,.12,'triangle',.1);tone(1047,.18,'triangle',.1,.09);},
  drum:()=>{for(let k=0;k<6;k++)tone(110+k*6,.08,'triangle',.07+k*.012,k*.11);}
};

/* ---- title ---- */
function renderTitle(){
  document.querySelectorAll('#segN button').forEach(b=>b.classList.toggle('on',+b.dataset.n===settings.n));
  $('#seats').innerHTML=settings.seats.slice(0,settings.n).map((s,i)=>`
    <div class="seat2" style="--pc:${AVC[AVS[i]]}">${avatarSVG(AVS[i])}<input data-i="${i}" value="${s.name.replace(/"/g,'&quot;')}" maxlength="8" aria-label="なまえ">
    <div class="seg"><button data-i="${i}" data-cpu="0" class="${!s.cpu?'on':''}">ひと</button><button data-i="${i}" data-cpu="1" class="${s.cpu?'on':''}">CPU</button></div></div>`).join('');
}
$('#segN').onclick=e=>{const b=e.target.closest('button');if(!b)return;settings.n=+b.dataset.n;save();renderTitle();SFX.tap();};
$('#seats').addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i;
  settings.seats[i].cpu=b.dataset.cpu==='1';
  if(settings.seats.slice(0,settings.n).every(s=>s.cpu))settings.seats[i].cpu=false;
  save();renderTitle();SFX.tap();
});
$('#seats').addEventListener('input',e=>{const i=+e.target.dataset.i;settings.seats[i].name=e.target.value;save();});
$('#hsStart').onclick=()=>{ac();SFX.tap();renderTitle();$('#setup').hidden=false;};
$('#setupBack').onclick=()=>{SFX.tap();$('#setup').hidden=true;};
// せってい: 今どれになっているかが見える切りかえ (前は「おとをオフにする」の押しボタンで、今の状態が分かりにくかった)
$('#setBtn').onclick=async()=>{ac();SFX.tap();
  const seg=(k,opts,cur)=>`<div class="seg" data-k="${k}">${opts.map(([v,l])=>`<button data-v="${v}" class="${v===cur?'on':''}">${l}</button>`).join('')}</div>`;
  const p=modal(`<h2>せってい</h2>
    <div class="srow"><div class="sl">おと</div>${seg('sound',[['1','オン'],['0','オフ']],settings.sound?'1':'0')}</div>
    <div class="srow"><div class="sl">はやさ<small>コンピュータが カードを出したあと、まつ時間。とちゅうで タップすれば すぐ次へ</small></div>${seg('speed',['slow','normal','fast'].map(k=>[k,PACES[k].label]),settings.speed)}</div>`,['とじる']);
  const box=$('#mbox');
  box.onclick=e=>{const b=e.target.closest('.srow .seg button');if(!b)return;const k=b.parentElement.dataset.k;
    if(k==='sound')settings.sound=b.dataset.v==='1';else settings.speed=b.dataset.v;
    save();SFX.tap();b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));};
  await p;box.onclick=null;
};
let stats={};try{stats=JSON.parse(localStorage.getItem('yakata-stats'))||{};}catch(e){}
function recordStats(){
  if(!G||!G.result)return;
  G.players.forEach(P=>{const k=P.name;const o=stats[k]||(stats[k]={g:0,w:0,cpu:P.cpu});o.g++;if(G.result.winners.includes(P.idx))o.w++;o.cpu=P.cpu;});
  try{localStorage.setItem('yakata-stats',JSON.stringify(stats));}catch(e){}
}
$('#rankBtn').onclick=async()=>{ac();SFX.tap();
  const list=Object.entries(stats).sort((a,b)=>b[1].w-a[1].w||(b[1].w/b[1].g)-(a[1].w/a[1].g)).slice(0,10);
  const html=list.length?list.map(([n,o],i)=>`<div class="rk"><span class="no">${['🥇','🥈','🥉'][i]||i+1}</span><span class="n">${n}${o.cpu?' <small style="color:#8a90a8">CPU</small>':''}</span><span class="w">${o.w}かち</span><span class="g">${o.g}かいちゅう<br>しょうりつ${Math.round(o.w/o.g*100)}%</span></div>`).join(''):'<p>まだ きろくが ありません。<br>あそぶと ここに のります!</p>';
  const empty=`<div class="empty">${AVS.map(a=>avatarSVG(a,'happy')).join('')}</div><p class="lead">まだ きろくが ないよ</p><p>あそぶと、かった回数が ここに のるよ!</p>`;
  const r=await modal(`<h2>ランキング</h2>${list.length?html:empty}`,list.length?['とじる','リセット']:['とじる']);
  if(r===1){const c=await modal('<h2>きろくを けす?</h2><p>ランキングが ぜんぶ きえます。</p>',['けす','やめる']);if(c===0){stats={};try{localStorage.removeItem('yakata-stats');}catch(e){}}}
};
$('#howBtn').onclick=()=>showRules();
$('#how2').onclick=()=>showRules();
$('#quit').onclick=async()=>{
  const r=await modal(`<h2>ゲームをやめる?</h2><p>タイトルにもどります。</p>`,['やめる','つづける']);
  if(r===0)location.reload();
};
$('#start').onclick=()=>{
  ac();SFX.tap();
  const seats=settings.seats.slice(0,settings.n).map((s,i)=>({name:(s.name||'').trim()||DEF_NAMES[i],cpu:s.cpu,av:AVS[i]}));
  newGame(seats);
  const humans=G.players.filter(P=>!P.cpu);
  G.viewer=humans.length===1?humans[0].idx:null;
  $('#setup').hidden=true;$('#title').hidden=true;$('#game').hidden=false;
  UI.render();
  runGame();
};

/* ---- modal ---- */
function modal(html,btns=['OK']){
  return new Promise(res=>{
    $('#mbox').innerHTML=html+`<div class="btns">${btns.map((b,i)=>`<button data-b="${i}" class="${i?'sec':''}">${b}</button>`).join('')}</div>`;
    $('#modal').hidden=false;
    $('#mbox').querySelectorAll('.btns button').forEach(b=>b.onclick=()=>{SFX.tap();$('#modal').hidden=true;res(+b.dataset.b);});
  });
}
// あそびかた: 1 ページに 1 つのことだけ。大きな字とカードの絵で、ページを送って読む (前は小さな字がびっしりで、子どもは読まなかった)
function showRules(){
  const pages=[
    ['どんな ゲーム?',`<div class="rc">${cardHTML({type:'hannin'})}</div><p class="lead"><b>「犯人」カード</b>を 持っている人が 犯人!</p><p>でも カードは こうかんされるので、犯人は どんどん かわるかも…!</p>`],
    ['すすめかた',`<div class="rc">${cardHTML({type:'hakken'})}</div><p class="lead"><b>「第一発見者」</b>を 持っている人から スタート</p><p>じゅんばんに 1まいずつ カードを出すと、そのカードの こうかが おきるよ。</p>`],
    ['かち・まけ',`<div class="rc">${cardHTML({type:'tantei'})}${cardHTML({type:'inu'})}</div><p class="lead"><b>探偵</b>か <b>いぬ</b>で 犯人を 見つけたら、みんなの かち!</p><p>犯人が さいごに <b>「犯人」カード</b>を 出せたら、犯人と なかまの かち!</p>`],
    ['カードの いみ',Object.keys(CARDS).map(t=>`<div class="crow">${cardHTML({type:t})}<div class="t"><b>${CARDS[t].n}</b> <small>${DECK_COUNTS[t]}まい</small><br>${CARDS[t].t}</div></div>`).join('')+`<p class="foot">3にん: 12まい・4にん: 16まいを つかいます。</p>`]
  ];
  let k=0;
  const draw=()=>{
    $('#rpage').innerHTML=`<h3 class="pt">${pages[k][0]}</h3><div class="rules${k===pages.length-1?' list':''}">${pages[k][1]}</div>`;
    $('#rdots').innerHTML=pages.map((_,i)=>`<i class="${i===k?'on':''}"></i>`).join('');
    $('#rprev').disabled=k===0;$('#rnext').disabled=k===pages.length-1;
    $('#rpage').scrollTop=0;
  };
  const p=modal(`<h2>あそびかた</h2><div id="rpage"></div><div class="rnav"><button id="rprev" aria-label="まえへ">◀</button><div id="rdots"></div><button id="rnext" aria-label="つぎへ">▶</button></div>`,['とじる']);
  $('#rprev').onclick=()=>{if(k>0){k--;SFX.tap();draw();}};
  $('#rnext').onclick=()=>{if(k<pages.length-1){k++;SFX.tap();draw();}};
  draw();
  return p;
}

/* ---- game UI ---- */
const ui={mode:'idle',sel:-1,resolve:null,legal:null,cands:null,btn:'出す'};
const UI={
  wait:ms=>new Promise(r=>setTimeout(r,ms)),
  sfx:k=>SFX[k]&&SFX[k](),
  humans:()=>G.players.filter(P=>!P.cpu).length,
  render(){
    if(!G)return;
    // 自分がえらぶ番は、場に大きな札を出す (手札の上の 1 行だけだと気づかなかった)
    const choosing=ui.mode==='give';
    $('#game').classList.toggle('choosing',choosing);
    const co=$('#callout');
    if(choosing){
      const t=ui.title||'',k=t.indexOf('!');
      const tag=k>=0?t.slice(0,k+1):'あなたが えらぶ番!',body=(k>=0?t.slice(k+1):t).trim().replace(/えらんでね$/,'<br>1まい えらんでね');
      const html=`<span class="tag">${tag}</span><div class="ct">${body}</div><div class="arw">▼</div>`;
      if(co.dataset.k!==t){co.innerHTML=html;co.dataset.k=t;}
      co.hidden=false;
    }else if(!co.hidden){co.hidden=true;co.dataset.k='';}
    const n=G.n;$('#players').style.gridTemplateColumns=`repeat(${n},1fr)`;
    $('#players').innerHTML=G.players.map(P=>{
      const pick=ui.mode==='target'&&ui.cands.includes(P.idx),dim=ui.mode==='target'&&!pick;
      return `<div class="pl ${G.turn===P.idx?'turn':''} ${P.idx===G.viewer?'me':''} ${pick?'pick':''} ${dim?'dim':''}" data-p="${P.idx}" style="--pc:${AVC[P.av]||'#6f6f78'}">
        ${P.idx===G.viewer&&P.name!=='あなた'?'<span class="you">あなた</span>':''}${P.acc?'<span class="tag">なかま</span>':''}
        ${avatarSVG(P.av,P.mood)}<div class="nm">${P.name}</div><div class="cnt">${'<i></i>'.repeat(P.hand.length)}</div></div>`;}).join('');
    // 場のカード: 新しく出たときだけ「ぽん」と出す (render は何度も呼ばれるので、毎回は動かさない)
    if(ui.shown!==G.last||ui.shownBy!==G.lastBy){
      ui.shown=G.last;ui.shownBy=G.lastBy;
      const by=G.players[G.lastBy],to=G.lastTo!=null?G.players[G.lastTo]:null;
      $('#played').innerHTML=G.last?`${cardHTML(G.last,{cls:'played'})}<div class="by">${byHTML(by)}${to?`<span class="to">▶</span>${byHTML(to)}`:'<span>が出した</span>'}</div>`:'';
      const pc=$('#played .card');
      if(pc&&pc.animate)pc.animate([{transform:'scale(.6) rotate(-8deg)',opacity:0},{transform:'scale(1.08) rotate(2deg)',opacity:1,offset:.6},{transform:'scale(1) rotate(0)'}],{duration:420,easing:'cubic-bezier(.2,.9,.3,1.2)'});
    }
    // 出したカードの行 (\u0003) は、場のカードと顔の列で見えているので出さない。そのカードで起きたことだけ、新しい 2 行
    const lp=G.log.map(s=>s[0]==='\u0003').lastIndexOf(true);
    $('#log').innerHTML=G.log.slice(lp+1).slice(-2).map(s=>`<div>${s.replace(/\u0001(\d+)\u0002/g,(m,i)=>whoHTML(G.players[i]))}</div>`).join('');
    // hand
    const V=G.viewer!=null?G.players[G.viewer]:null;
    if(!V){$('#hand').innerHTML='<div class="hid">手札は かくしています</div>';}
    else if(!V.hand.length){$('#hand').innerHTML='<div class="hid">手札は もう ありません</div>';}
    else{
      // 手札の大きさは枚数で決める: 少ないときは大きく (112pt まで)、多いときは横幅に収める (はみ出すと端のカードが切れた)
      const hw=$('#hand').clientWidth||406,n=V.hand.length;
      $('#hand').style.setProperty('--cw',Math.min(112,Math.floor((hw-(n-1)*8)/n))+'px');
    }
    if(V&&V.hand.length)$('#hand').innerHTML=V.hand.map((c,i)=>{
      const ng=ui.mode==='play'&&!ui.legal.includes(i);
      return cardHTML(c,{cls:(ui.sel===i?'sel ':'')+(ng?'ng':''),data:`data-ci="${i}"`,fresh:true});}).join('');
    // info
    const go=$('#go');
    if(ui.mode==='play'||ui.mode==='give'){
      if(ui.sel>=0&&V){
        const c=V.hand[ui.sel],ok=ui.mode==='give'||ui.legal.includes(ui.sel);
        // 出せないときは、説明の代わりに理由を出す (帯に収めるため。いちばん知りたいのは理由)
        $('#infoTxt').innerHTML=`<b>${CARDS[c.type].n}</b>　${ok?CARDS[c.type].t:`<span class="ng">※ ${whyNot(V,c)}</span>`}`;
        go.disabled=!ok;
      }else{$('#infoTxt').innerHTML='';go.disabled=true;}   // 案内は上の行にあるので、ここでは くり返さない
      go.textContent=ui.btn;go.hidden=false;
    }else if(ui.mode==='target'){
      $('#infoTxt').innerHTML=`<b>${CARDS[V.hand[ui.sel].type].n}</b><br>上の人を タップしてね`;go.hidden=true;
    }else{
      const T=G.turn>=0?G.players[G.turn]:null;
      $('#infoTxt').innerHTML=ui.reading?'<span class="next">タップで つぎへ ▸</span>':T&&!G.over?(T.cpu?`<span class="wait">${byHTML(T)} かんがえ中…</span>`:`${T.name} の番`):'';go.hidden=true;
    }
  },
  setPrompt(html){$('#prompt').innerHTML=html||'';},
  async ensureViewer(i){
    if(G.viewer===i)return;
    G.viewer=null;UI.render();
    const P=G.players[i];
    const h=$('#handoff');
    h.innerHTML=`<div class="big-av">${avatarSVG(P.av)}</div><h2>${P.name} さんの番</h2><p>スマホを ${P.name} さんに わたしてね。<br>ほかの人は 見ないでね!</p><button>わたしが ${P.name}</button>`;
    h.hidden=false;
    await new Promise(r=>h.querySelector('button').onclick=()=>{SFX.tap();r();});
    h.hidden=true;G.viewer=i;UI.render();
  },
  // ms だけ待つ。そのあいだに場をタップしたら、すぐ次へ (ボタンや手札のタップは数えない)
  readPause(ms){
    return new Promise(res=>{
      const g=$('#game');let done=false;
      const end=()=>{if(done)return;done=true;clearTimeout(tm);g.removeEventListener('pointerdown',tap,true);ui.reading=false;UI.render();res();};
      const tap=e=>{if(e.target.closest('button,#hand,#bar'))return;end();};
      const tm=setTimeout(end,ms);
      ui.reading=true;UI.render();
      g.addEventListener('pointerdown',tap,true);
    });
  },
  afterTurn(i){
    if(UI.humans()>1&&!G.over){G.viewer=null;UI.render();}
  },
  humanTurn(i){
    return new Promise(res=>{
      const P=G.players[i];
      ui.mode='play';ui.sel=-1;ui.legal=legalIdx(P);ui.btn='出す';ui.resolve=res;
      UI.setPrompt('あなたの番! カードを1まい出そう');
      UI.render();SFX.myturn();
      const pr=$('#prompt');if(pr.animate)pr.animate([{transform:'scale(.8)',opacity:0},{transform:'scale(1.12)',opacity:1,offset:.6},{transform:'scale(1)'}],{duration:380,easing:'ease-out'});
    });
  },
  pickGive(i,title){
    return new Promise(res=>{
      ui.mode='give';ui.sel=-1;ui.legal=G.players[i].hand.map((c,k)=>k);ui.btn='わたす';ui.resolve=res;ui.title=title;
      UI.setPrompt(title);UI.render();SFX.secret();
    });
  },
  // 場の上に重ねる知らせ。OK を押させず、時間がたつか 場をタップすると消える (OK だらけで流れが止まっていた)
  async announce(who,html,card,mood,ms){
    const P=G.players[who];
    const b=document.createElement('div');b.className='banner';
    b.innerHTML=`<div class="bx" style="--pc:${AVC[P.av]||'#6f6f78'}"><div class="bav">${avatarSVG(P.av,mood)}</div><div class="bt">${html}</div>${card?cardHTML(card,{cls:'mini'}):''}</div>`;
    $('#table').appendChild(b);
    const bx=b.firstChild;
    if(bx.animate)bx.animate([{transform:'scale(.7)',opacity:0},{transform:'scale(1.04)',opacity:1,offset:.7},{transform:'scale(1)'}],{duration:300,easing:'ease-out'});
    await UI.readPause(ms||Math.max(1600,pace().read));
    b.remove();
  },
  // その人のいる所 (手札を見ている人なら手札、ほかは上のタイル) の真ん中
  spot(i){
    const el=i===G.viewer&&UI.humans()===1?$('#hand'):document.querySelector(`#players .pl[data-p="${i}"]`);
    const r=(el||$('#table')).getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2};
  },
  tableSpot(){const r=$('#played').getBoundingClientRect(),t=$('#table').getBoundingClientRect();return {x:t.left+t.width/2,y:r.height>60?r.top+r.height*.4:t.top+t.height*.38};},
  // カードを ある所から ある所へ飛ばす (位置は left/top、動きは transform だけ。落とし穴の表)
  fly(from,to,html,ms=560){
    const f=document.createElement('div');f.className='fly';f.innerHTML=html;
    f.style.left=from.x+'px';f.style.top=from.y+'px';document.body.appendChild(f);
    const dx=to.x-from.x,dy=to.y-from.y;
    if(f.animate)f.animate([
      {transform:'translate(-50%,-50%) scale(.6) rotate(-10deg)',opacity:.4},
      {transform:`translate(calc(-50% + ${dx/2}px),calc(-50% + ${dy/2-36}px)) scale(1.05) rotate(5deg)`,opacity:1,offset:.5},
      {transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(.7) rotate(0)`,opacity:1}],{duration:ms,easing:'cubic-bezier(.45,0,.25,1)',fill:'forwards'});
    UI.flights=(UI.flights||0)+1;
    return new Promise(r=>setTimeout(()=>{f.remove();r();},ms));
  },
  // 出したカードが、出した人の所から場へ飛んでいく
  flyPlay(i,c,fromEl){
    let from=UI.spot(i);
    if(fromEl){const r=fromEl.getBoundingClientRect();from={x:r.left+r.width/2,y:r.top+r.height/2};}
    return UI.fly(from,UI.tableSpot(),cardHTML(c,{cls:'flyc'}),460);
  },
  // カードが人から人へうつる。自分が出す・もらうカードは表、ほかの人どうしは裏で飛ぶ
  flyTransfers(trs){
    const me=UI.humans()===1?G.players.find(P=>!P.cpu).idx:null;
    return Promise.all(trs.map((t,k)=>UI.wait(k*110).then(()=>UI.fly(UI.spot(t.from),UI.spot(t.to),
      me!=null&&(t.from===me||t.to===me)?cardHTML(t.card,{cls:'flyc'}):'<div class="card back flyc"></div>',680))));
  },
  async privateMsg(i,html,cards){
    SFX.secret();
    await modal(`${html}${cards?`<div class="cards">${cards.map(c=>cardHTML(c,{cls:'mini'})).join('')}</div>`:''}<p style="font-size:12px;color:#8a90a8">ほかの人には ないしょ!</p>`,['おぼえた']);
  },
  // カードの行き来は、飛んでいく動きで見せる。自分が犯人になった / 手ばなしたときだけ知らせを重ねる
  async moveNotice(trs){
    await UI.flyTransfers(trs);
    UI.render();
    if(UI.humans()!==1)return;
    const h=G.players.find(P=>!P.cpu).idx;const out=trs.find(t=>t.from===h),inn=trs.find(t=>t.to===h);
    if(inn&&inn.card.type==='hannin'){UI.sfx('hit');await UI.announce(h,'<p class="lead">あなたが 犯人に なった…!</p>',inn.card,'shock');}
    else if(out&&out.card.type==='hannin')await UI.announce(h,'<p class="lead">犯人カードを 手ばなした!</p><p>もう 犯人じゃない。</p>',out.card,'happy');
  },
  showResult(){
    const R=G.result,C=G.players[R.crimIdx],A=G.players[R.actor];
    let head='';
    if(R.kind==='hannin')head=`<h2>犯人の にげきり!</h2><p>${C.name} が さいごに「犯人」カードを出した!</p>`;
    if(R.kind==='tantei')head=`<h2>めいたんてい!</h2><p>${A.name} が 犯人 <b>${C.name}</b> を 見やぶった!</p>`;
    if(R.kind==='inu')head=`<h2>いぬの お手がら!</h2><p>${A.name} のいぬが 犯人カードを くわえてきた!<br>犯人は <b>${C.name}</b></p>`;
    const vw=UI.humans()===1?G.players.find(P=>!P.cpu).idx:null;
    if(vw!=null)head=`<div class="big-av">${avatarSVG(G.players[vw].av,G.players[vw].mood)}</div><p style="font-size:26px;font-weight:900;margin:0;color:${R.winners.includes(vw)?'#f1d78c':'#9aa0b8'}">${R.winners.includes(vw)?'かち!':'まけ…'}</p>`+head;
    (vw==null||R.winners.includes(vw))?SFX.win():SFX.lose();
    const rows=G.players.map(P=>{
      const w=R.winners.includes(P.idx);
      const role=P.idx===R.crimIdx?'犯人':(P.acc?'なかま':'');
      return `<div class="res ${w?'win':''}">${avatarSVG(P.av,P.mood)}<div class="who"><b>${P.name}</b>${role?` <span style="font-size:11px;color:#ff9b8a">${role}</span>`:''}
        <div class="mh">${P.hand.map(c=>`<span style="--c:${CARDS[c.type].c}">${CARDS[c.type].n}</span>`).join('')||'<span style="--c:#999">手札なし</span>'}</div></div><div class="st">${w?'かち':'まけ'}</div></div>`;
    }).join('');
    G.viewer=vw;UI.render();recordStats();
    modal(head+rows,['もういちど','タイトルへ']).then(b=>{
      if(b===0){$('#start').onclick();}else{G=null;$('#game').hidden=true;$('#title').hidden=false;renderTitle();}
    });
  }
};

$('#hand').addEventListener('click',e=>{
  const el=e.target.closest('.card');if(!el||!(ui.mode==='play'||ui.mode==='give'))return;
  const i=+el.dataset.ci;ui.sel=ui.sel===i?-1:i;SFX.tap();UI.render();
});
$('#go').onclick=()=>{
  if(ui.sel<0)return;SFX.tap();
  const V=G.players[G.viewer];
  if(ui.mode==='give'){const r=ui.resolve,s=ui.sel;ui.mode='idle';ui.sel=-1;UI.setPrompt('');UI.render();r(s);return;}
  const c=V.hand[ui.sel];
  if(NEEDS_TARGET[c.type]){
    const cands=withCards(V.idx);
    if(cands.length){
      ui.mode='target';ui.cands=cands;
      UI.setPrompt(`だれに つかう? <button id="cancelT">やめる</button>`);
      $('#cancelT').onclick=()=>{ui.mode='play';UI.setPrompt('あなたの番! カードを1まい出そう');UI.render();};
      UI.render();return;
    }
  }
  const r=ui.resolve,s=ui.sel;ui.mode='idle';ui.sel=-1;UI.setPrompt('');UI.render();r({ci:s,target:null});
};
$('#players').addEventListener('click',e=>{
  if(ui.mode!=='target')return;const el=e.target.closest('.pl');if(!el)return;
  const p=+el.dataset.p;if(!ui.cands.includes(p))return;SFX.tap();
  const r=ui.resolve,s=ui.sel;ui.mode='idle';ui.sel=-1;UI.setPrompt('');UI.render();r({ci:s,target:p});
});

renderTitle();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
